// Writes README.md from its sources (`pnpm turbo run build`); `--check` fails when README.md is stale.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { type Content, SITE_URL, loadContent, repoRoot } from "./content.ts";

export function render(c: Content): string {
  return (
    [
      "# agents",
      "<!-- Generated by lib/tools/build/readme.ts. Edit docs/_intro.md and docs/_install.md, then run pnpm turbo run readme. -->",
      c.intro,
      `[Browse ${c.plugins.length} plugins](${SITE_URL}/plugins/) · [Browse ${c.skills.length} skills](${SITE_URL}/skills/)`,
      "## Try one",
      c.install,
      "## Development",
      "The [developer guide](docs/development.md) covers local setup, tests, and packaging for Claude Code, pi, and Nix.",
    ].join("\n\n") + "\n"
  );
}

/** What is wrong with README.md: empty when it is the generator's output. */
export function checkReadme(root: string = repoRoot): string[] {
  const file = join(root, "README.md");
  const have = existsSync(file) ? readFileSync(file, "utf8") : "";
  return have === render(loadContent(root))
    ? []
    : ["README.md is stale: run `pnpm turbo run build` (then `pnpm turbo run fmt`) and commit it."];
}

// Imported by the invariants spec, which only calls `checkReadme`.
if (import.meta.main) {
  if (process.argv.includes("--check")) {
    const problems = checkReadme();
    if (problems.length) {
      console.error(problems.join("\n"));
      process.exit(1);
    }
  } else {
    writeFileSync(join(repoRoot, "README.md"), render(loadContent(repoRoot)));
  }
}
